// requiredEnv are the variables that the test config reads, besides the API key.
var requiredEnv = []string{}

// providerFactories serve the provider as the binary does: the SDKv2 and the framework providers
// behind one mux, so a prerequisite can be any resource of the provider.
var providerFactories = map[string]func() (tfprotov6.ProviderServer, error){
	"coralogix": func() (tfprotov6.ProviderServer, error) {
		server, err := provider.MuxServer(context.Background())
		if err != nil {
			return nil, err
		}
		return server(), nil
	},
}

func preCheck(t *testing.T) {
	t.Helper()
	if os.Getenv("CORALOGIX_API_KEY") == "" {
		t.Fatal("CORALOGIX_API_KEY must be set for acceptance tests")
	}
	if os.Getenv("CORALOGIX_ENV") == "" && os.Getenv("CORALOGIX_DOMAIN") == "" {
		t.Fatal("CORALOGIX_ENV or CORALOGIX_DOMAIN must be set for acceptance tests")
	}
	for _, name := range requiredEnv {
		if os.Getenv(name) == "" {
			t.Fatalf("%s must be set for acceptance tests", name)
		}
	}
}

// render replaces @{run} and @{env.NAME}.
func render(run, text string) string {
	pairs := []string{"@{run}", run}
	for _, name := range requiredEnv {
		pairs = append(pairs, "@{env."+name+"}", os.Getenv(name))
	}
	return strings.NewReplacer(pairs...).Replace(text)
}

