func newRun() string { return "acc-" + uuid.NewString()[:8] }

// importStep imports the resource and compares the imported state with the state.
var importStep = resource.TestStep{
	ResourceName:      resourceAddress,
	ImportState:       true,
	ImportStateVerify: true,
}

// importPlanStep imports the resource with an import block, into a config that leaves every optional
// attribute out, and fails when the plan is not a no-op. The import has no prior state, so the read
// alone decides each empty value (null, [] or {}): a value that the API returns as [] or {} for an
// attribute that the config leaves out shows up here as a change.
var importPlanStep = resource.TestStep{
	ResourceName:    resourceAddress,
	ImportState:     true,
	ImportStateKind: resource.ImportBlockWithID,
}

// TestAccCoralogixResourceAlertGenerated runs one lifecycle per subtest, each on its own resource,
// so that a failure in one does not hide the others. After every apply, the framework plans again and
// fails when the plan is not empty.
func TestAccCoralogixResourceAlertGenerated(t *testing.T) {
	failreport.Install() // records the HTTP calls that ErrorCheck shows in the line of a failure
	// full-lifecycle sets every attribute, imports, reads the data source, changes the attributes, and imports again.
	t.Run("full-lifecycle", func(t *testing.T) {
		run := newRun()
		resource.Test(t, resource.TestCase{
			PreCheck:                 func() { preCheck(t) },
			ProtoV6ProviderFactories: providerFactories,
			ErrorCheck:               failreport.ErrorCheck(apiFields),
			Steps: failreport.Steps(t, []resource.TestStep{
				{Config: config(run, fullConfig), Check: fullChecks(run)},
				importStep,
				{Config: config(run, fullConfig+"\n\n"+dataSourceConfig), Check: dataSourceChecks()},
				{Config: config(run, updatedConfig), Check: updatedChecks(run)},
				importStep,
			}),
		})
	})

	// minimal-lifecycle creates the resource with only the required attributes, imports it (also with
	// a plan-only import that must show no change), sets every attribute, and removes them again.
	t.Run("minimal-lifecycle", func(t *testing.T) {
		run := newRun()
		resource.Test(t, resource.TestCase{
			PreCheck:                 func() { preCheck(t) },
			ProtoV6ProviderFactories: providerFactories,
			ErrorCheck:               failreport.ErrorCheck(apiFields),
			Steps: failreport.Steps(t, []resource.TestStep{
				{Config: config(run, minimalConfig), Check: minimalChecks(run)},
				importStep,
				importPlanStep,
				{Config: config(run, fullConfig), Check: fullChecks(run)},
				{Config: config(run, minimalConfig), Check: removedChecks(run)},
				importStep,
			}),
		})
	})

	// values-and-choices sends every enum value and every oneOf arm to the API. It applies the full
	// config, then one config for each step of the generator: a step sets the values and the arms
	// that no earlier config sets, in the elements of its lists and in copies of the resource. After each apply, the framework plans again and fails when the
	// plan is not empty, so a value that the API changes or drops fails the step. A value or an arm
	// that the tenant refuses goes in skipValues or skipChoices of the acceptance file, with the reason.
	t.Run("values-and-choices", func(t *testing.T) {
		run := newRun()
		resource.Test(t, resource.TestCase{
			PreCheck:                 func() { preCheck(t) },
			ProtoV6ProviderFactories: providerFactories,
			ErrorCheck:               failreport.ErrorCheck(apiFields),
			Steps: failreport.Steps(t, []resource.TestStep{
				{Config: config(run, fullConfig), Check: fullChecks(run)},
				{Config: config(run, variant1Config), Check: variant1Checks(run)},
				{Config: config(run, variant2Config), Check: variant2Checks(run)},
				{Config: config(run, variant3Config), Check: variant3Checks(run)},
				{Config: config(run, variant4Config), Check: variant4Checks(run)},
				{Config: config(run, variant5Config), Check: variant5Checks(run)},
				{Config: config(run, variant6Config), Check: variant6Checks(run)},
				{Config: config(run, variant7Config), Check: variant7Checks(run)},
				{Config: config(run, variant8Config), Check: variant8Checks(run)},
				{Config: config(run, variant9Config), Check: variant9Checks(run)},
			}),
		})
	})
}

// TestFailurePathsAlertGenerated checks, without a tenant, what the resource does when the API
// fails: a local server answers every request with an error (failpaths.Run). It needs no API key.
func TestFailurePathsAlertGenerated(t *testing.T) {
	for _, name := range requiredEnv {
		if os.Getenv(name) == "" {
			t.Skipf("%s is not set: the test config reads it", name)
		}
	}
	failpaths.Run(t, failpaths.Spec{
		ProviderServer: func() (tfprotov6.ProviderServer, error) { return providerFactories["coralogix"]() },
		TypeName:       "coralogix_alert",
		IDAttr:         "id",
		Config:         render("failure-paths", minimalConfig),
	})
}

// TestConfigsValidateAlertGenerated checks, without a tenant and without an API key, that the
// schema accepts every config of this file: the values of an enum, the fields that a oneOf holds
// together, and the rules between fields (failpaths.ValidateConfigs). The API is not called, so a
// value that only the API refuses fails in the acceptance tests.
func TestConfigsValidateAlertGenerated(t *testing.T) {
	pairs := []string{"@{run}", "acc-offline"}
	for _, name := range requiredEnv {
		pairs = append(pairs, "@{env."+name+"}", "offline")
	}
	offline := strings.NewReplacer(pairs...)
	failpaths.ValidateConfigs(t, failpaths.Spec{
		ProviderServer: func() (tfprotov6.ProviderServer, error) { return providerFactories["coralogix"]() },
		TypeName:       "coralogix_alert",
	}, map[string]string{
		"full":     offline.Replace(fullConfig),
		"updated":  offline.Replace(updatedConfig),
		"minimal":  offline.Replace(minimalConfig),
		"variant1": offline.Replace(variant1Config),
		"variant2": offline.Replace(variant2Config),
		"variant3": offline.Replace(variant3Config),
		"variant4": offline.Replace(variant4Config),
		"variant5": offline.Replace(variant5Config),
		"variant6": offline.Replace(variant6Config),
		"variant7": offline.Replace(variant7Config),
		"variant8": offline.Replace(variant8Config),
		"variant9": offline.Replace(variant9Config),
	})
}

const (
	// One variable switches on the upgrade tests of every generated resource.
	upgradeEnv     = "CORALOGIX_GENERATED_UPGRADE_ACC"
	upgradeSource  = "registry.terraform.io/coralogix/coralogix"
	upgradeVersion = "= 3.24.0"
)

func requireUpgradeAcceptance(t *testing.T) {
	t.Helper()
	if os.Getenv(upgradeEnv) == "" {
		t.Skipf("set %s=1 to run the registry-backed upgrade test", upgradeEnv)
	}
	if namespace := os.Getenv(resource.EnvTfAccProviderNamespace); namespace != "coralogix" {
		t.Fatalf("set %s=coralogix to run the registry-backed upgrade test", resource.EnvTfAccProviderNamespace)
	}
}

// upgradeSteps creates the resource with the released provider, then plans the same config with this
// build and expects no change, applies the config next with the plan checks nextPlan, and imports.
func upgradeSteps(run, initial string, initialChecks resource.TestCheckFunc, next string, nextChecks resource.TestCheckFunc, nextPlan []plancheck.PlanCheck) []resource.TestStep {
	importWithBuild := importStep
	importWithBuild.ProtoV6ProviderFactories = providerFactories
	return []resource.TestStep{
		{
			Config: config(run, initial),
			ExternalProviders: map[string]resource.ExternalProvider{
				"coralogix": {Source: upgradeSource, VersionConstraint: upgradeVersion},
			},
			Check: initialChecks,
		},
		{
			// This build reads the state of the released provider and plans no change.
			Config:                   config(run, initial),
			ProtoV6ProviderFactories: providerFactories,
			ConfigPlanChecks: resource.ConfigPlanChecks{
				PreApply:             []plancheck.PlanCheck{plancheck.ExpectResourceAction(resourceAddress, plancheck.ResourceActionNoop)},
				PostApplyPostRefresh: []plancheck.PlanCheck{plancheck.ExpectEmptyPlan()},
			},
			Check: initialChecks,
		},
		{
			Config:                   config(run, next),
			ProtoV6ProviderFactories: providerFactories,
			ConfigPlanChecks: resource.ConfigPlanChecks{
				PreApply:             nextPlan,
				PostApplyPostRefresh: []plancheck.PlanCheck{plancheck.ExpectEmptyPlan()},
			},
			Check: nextChecks,
		},
		importWithBuild,
	}
}

// upgradeNoopSteps creates the resource with the released provider, then plans the same config with
// this build and expects no change. There is no later update or import: a write-only value does not
// round-trip on import.
func upgradeNoopSteps(run, initial string, initialChecks resource.TestCheckFunc) []resource.TestStep {
	return []resource.TestStep{
		{
			Config: config(run, initial),
			ExternalProviders: map[string]resource.ExternalProvider{
				"coralogix": {Source: upgradeSource, VersionConstraint: upgradeVersion},
			},
			Check: initialChecks,
		},
		{
			Config:                   config(run, initial),
			ProtoV6ProviderFactories: providerFactories,
			ConfigPlanChecks: resource.ConfigPlanChecks{
				PreApply:             []plancheck.PlanCheck{plancheck.ExpectResourceAction(resourceAddress, plancheck.ResourceActionNoop)},
				PostApplyPostRefresh: []plancheck.PlanCheck{plancheck.ExpectEmptyPlan()},
			},
			Check: initialChecks,
		},
	}
}

// expectNoReplace fails when the plan replaces the resource. The step may update the resource or
// leave it as it is: a default in state can equal what the next config sets.
type expectNoReplace struct{}

func (expectNoReplace) CheckPlan(_ context.Context, req plancheck.CheckPlanRequest, resp *plancheck.CheckPlanResponse) {
	for _, change := range req.Plan.ResourceChanges {
		if change.Address == resourceAddress && change.Change.Actions.Replace() {
			resp.Error = fmt.Errorf("%s: the plan replaces the resource, want an update or no change", resourceAddress)
		}
	}
}

// TestAccCoralogixResourceAlertGeneratedUpgrade creates the resource with provider 3.24.0, then plans
// the same config with this build. A user who upgrades must see no change, and a later update must
// work. Set CORALOGIX_GENERATED_UPGRADE_ACC=1 and TF_ACC_PROVIDER_NAMESPACE=coralogix to run it.
func TestAccCoralogixResourceAlertGeneratedUpgrade(t *testing.T) {
	requireUpgradeAcceptance(t)

	t.Run("upgrade-full", func(t *testing.T) {
		run := newRun()
		resource.Test(t, resource.TestCase{
			PreCheck: func() { preCheck(t) },
			Steps: upgradeSteps(run, upgradeFullConfig, upgradeFullChecks(run),
				updatedConfig, updatedChecks(run), []plancheck.PlanCheck{expectNoReplace{}}),
		})
	})

	// upgrade-minimal starts from the fewest attributes that the released provider accepts.
	t.Run("upgrade-minimal", func(t *testing.T) {
		run := newRun()
		resource.Test(t, resource.TestCase{
			PreCheck: func() { preCheck(t) },
			Steps:    upgradeSteps(run, upgradeMinimalConfig, upgradeMinimalChecks(run), fullConfig, fullChecks(run), []plancheck.PlanCheck{expectNoReplace{}}),
		})
	})

	t.Run("upgrade-schedule", func(t *testing.T) {
		run := newRun()
		resource.Test(t, resource.TestCase{
			PreCheck: func() { preCheck(t) },
			Steps:    upgradeNoopSteps(run, upgradeScheduleConfig, upgradeScheduleChecks(run)),
		})
	})
}

